import{$ as e,A as t,B as n,V as r}from"./chunks/framework.DrAJjmzW.js";var i=JSON.parse(`{"title":"Apps","description":"","frontmatter":{"title":"Apps","hide":["navigation"]},"headers":[],"relativePath":"apps.md","filePath":"apps.md","lastUpdated":1788401923000}`),a={name:`apps.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="apps-page" tabindex="-1">Apps Page <a class="header-anchor" href="#apps-page" aria-label="Permalink to “Apps Page”">​</a></h1><p>The <strong>Apps Page</strong> is a comprehensive app installer that supports both <strong>Winget</strong> and <strong>Chocolatey</strong> package managers to install or uninstall applications on your system.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to “Features”">​</a></h2><h3 id="package-manager-support" tabindex="-1">Package Manager Support <a class="header-anchor" href="#package-manager-support" aria-label="Permalink to “Package Manager Support”">​</a></h3><p>Sparkle supports two package managers:</p><ul><li><strong>Winget</strong> - Windows Package Manager (default)</li><li><strong>Chocolatey</strong> - Community package manager</li></ul><p>You can switch between them using the <strong>Select Source</strong> dropdown. The page will automatically detect if your selected package manager is installed and offer to install it if missing.</p><h3 id="search-and-categories" tabindex="-1">Search and Categories <a class="header-anchor" href="#search-and-categories" aria-label="Permalink to “Search and Categories”">​</a></h3><p>The Apps page displays over 100+ applications organized into categories:</p><ul><li><strong>Browsers</strong> - Firefox, Chrome, Brave, Opera, Vivaldi, Tor Browser, Zen Browser, and more</li><li><strong>Communication</strong> - Discord, Slack, Teams, Telegram, Zoom, Signal, Vesktop</li><li><strong>Development</strong> - VS Code, Visual Studio, Git, GitHub Desktop, Node.js, Docker, Python, Rust, Go</li><li><strong>Games</strong> - Steam, Epic Games, EA App, Battle.net, Minecraft Launcher, Playnite, Modrinth</li><li><strong>Multimedia</strong> - Spotify, VLC, OBS Studio, Audacity, Krita, ShareX, FxSound</li><li><strong>Productivity</strong> - Notion, Dropbox, Microsoft Office, Blender</li><li><strong>Privacy &amp; Security</strong> - VPN services (Surfshark, NordVPN, Proton VPN, Mullvad), Bitwarden, Malwarebytes</li><li><strong>Utilities</strong> - 7-Zip, PowerToys, Rufus, MSI Afterburner, Everything Search, and many more</li><li><strong>Python</strong> - Multiple Python versions (3.8 through 3.13)</li></ul><p>Use the search bar to quickly find apps by name.</p><h3 id="install-and-uninstall" tabindex="-1">Install and Uninstall <a class="header-anchor" href="#install-and-uninstall" aria-label="Permalink to “Install and Uninstall”">​</a></h3><ol><li>Select apps by clicking on them or using the checkbox</li><li>Click <strong>Install Selected</strong> to install</li><li>Click <strong>Uninstall Selected</strong> to remove apps</li></ol><p>The Install/Uninstall status is in the titlebar.</p><h3 id="export-and-import" tabindex="-1">Export and Import <a class="header-anchor" href="#export-and-import" aria-label="Permalink to “Export and Import”">​</a></h3><p>You can export your selected apps list to share or backup:</p><ul><li><strong>Export List</strong> - Downloads a JSON file with your selected apps</li><li><strong>Import List</strong> - Import a previously exported JSON file to select those apps</li></ul><h2 id="app-cards" tabindex="-1">App Cards <a class="header-anchor" href="#app-cards" aria-label="Permalink to “App Cards”">​</a></h2><p>Each app displays:</p><ul><li>App icon</li><li>App name</li><li>Description</li><li>Package ID</li><li>External link button to open the app&#39;s website</li></ul><p>Some apps may show a warning if they have known installation issues when running as admin.</p><h2 id="contributing-new-apps" tabindex="-1">Contributing New Apps <a class="header-anchor" href="#contributing-new-apps" aria-label="Permalink to “Contributing New Apps”">​</a></h2><p>To add new apps to the installer, edit the <code>apps.json</code> file located at:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>src/renderer/assets/apps.json</span></span></code></pre></div><p>Each app entry has the following structure:</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;App Name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Publisher.AppName&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;chocolatey&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;package-name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;category&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;category-name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;info&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Short description of the app.&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;link&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://example.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;icon&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://example.com/icon.png&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to “Fields”">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>Yes</td><td>Display name of the app</td></tr><tr><td><code>id</code></td><td>Yes*</td><td>Winget package ID</td></tr><tr><td><code>chocolatey</code></td><td>No</td><td>Chocolatey package name</td></tr><tr><td><code>category</code></td><td>Yes</td><td>Category for grouping (e.g., &quot;browsers&quot;, &quot;development&quot;)</td></tr><tr><td><code>info</code></td><td>Yes</td><td>Short description shown on the app card</td></tr><tr><td><code>link</code></td><td>No</td><td>Website URL (opens in external link)</td></tr><tr><td><code>icon</code></td><td>Yes</td><td>URL to the app&#39;s icon image</td></tr><tr><td><code>warning</code></td><td>No</td><td>Optional warning message displayed to users</td></tr></tbody></table><p>*Required for Winget source. Some apps may only have a Chocolatey package.</p><p>After editing, submit a pull request on <a href="https://github.com/parcoil/sparkle" target="_blank" rel="noreferrer">GitHub</a>.</p>`,30)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};